result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/statute.py", "content": """"Statute-of-limitations calculator with tolling (invented rule set).

Rules (encoded as constants):
- Breach-of-contract claims expire LIMIT_YEARS after accrual.
- The clock is tolled (paused):
    * while the plaintiff is a minor (until their MAJORITY_AGE birthday),
    * during any defendant-absence intervals (inclusive date ranges).
- Overlapping tolling intervals must not double count.
- Tolled intervals are clipped to start no earlier than the accrual date;
  anything entirely before accrual has no effect.
- The deadline is pushed out by the total number of tolled days.
"""

from __future__ import annotations

from datetime import date, timedelta

# --- Invented rule-set constants -------------------------------------------
LIMIT_YEARS = 4       # breach of contract
MAJORITY_AGE = 18     # tolling while plaintiff is a minor


def _add_years(d: date, n: int) -> date:
    """Add n calendar years, mapping Feb 29 -> Feb 28 in non-leap years."""
    try:
        return d.replace(year=d.year + n)
    except ValueError:  # Feb 29 in a non-leap target year
        return d.replace(year=d.year + n, month=2, day=28)


def _merge_intervals(
    intervals: list[tuple[date, date]],
) -> list[tuple[date, date]]:
    """Merge overlapping/touching closed intervals so time is not double counted."""
    ordered = sorted(intervals)
    merged: list[list[date]] = []
    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [(s, e) for s, e in merged]


def _tolling_intervals(
    accrual: date,
    dob: date | None,
    absences: list[tuple[date, date]],
) -> list[tuple[date, date]]:
    """Collect, normalize, and merge all tolling intervals."""
    intervals: list[tuple[date, date]] = []
    if dob is not None:
        intervals.append((dob, _add_years(dob, MAJORITY_AGE)))
    for start, end in absences:
        intervals.append((min(start, end), max(start, end)))
    return _merge_intervals(intervals)


def tolled_days(
    accrual: date,
    dob: date | None,
    absences: list[tuple[date, date]],
) -> int:
    """Total number of distinct tolled days attributable to this claim."""
    total = 0
    for start, end in _tolling_intervals(accrual, dob, absences):
        start = max(start, accrual)  # clip to [accrual, open end)
        if end >= start:
            total += (end - start).days + 1  # closed interval: inclusive span
    return total


def expiry(
    accrual: date,
    dob: date | None,
    absences: list[tuple[date, date]],
) -> date:
    """Return the date the limitations period expires.

    Base deadline = accrual + LIMIT_YEARS (calendar years, Feb 29 safe),
    then pushed out by every tolled day, each counted once.
    """
    return _add_years(accrual, LIMIT_YEARS) + timedelta(days=tolled_days(accrual, dob, absences))
